{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var save_data := {"score": 150, "level": 2}
	if "score" in save_data:
		return save_data["score"]
	return 0
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`"score" in save_data` è vero perché la chiave esiste nel dizionario. Viene restituito il valore associato, cioè `150`."
  },
  {
   "codice": "extends RefCounted


func run():
	var target_has_die := true
	var target_has_respawn := false
	var result := ""
	if target_has_die:
		result = "die"
	elif target_has_respawn:
		result = "respawn"
	else:
		result = "none"
	return result
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`target_has_die` è `true`, quindi la prima condizione dell'if è subito vera. Viene assegnato e restituito "die"."
  },
  {
   "codice": "extends RefCounted


func run():
	var target_name := "Player"
	var is_enemy := false
	var is_valid := (target_name == "Player") or is_enemy
	return is_valid
",
   "domanda": "Cosa restituisce `run()` (vero o falso)?",
   "spiegazione": "`target_name == "Player"` è vero. Con l'operatore `or`, basta che una delle due condizioni sia vera perché l'intero risultato sia `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var current_level := 3
	var max_levels := 5
	var is_last := current_level >= max_levels
	return is_last
",
   "domanda": "Cosa restituisce `run()` (vero o falso)?",
   "spiegazione": "`current_level` è 3 e `max_levels` è 5. 3 non è maggiore o uguale a 5, quindi il confronto restituisce `false`."
  }
 ]
